  "board.title": "Prikbord",
  "board.lead": "Korte briefjes voor de scene — geen lange discussie.",
  "board.purpose": "Hang een briefje op als je een speler zoekt, een chart, een zaal, of een jam wilt vullen. Zet de stad, de avond en wat je nodig hebt. Houd het kort, zodat iemand vanavond ja kan zeggen.",
  "board.use.looking": "Speler gezocht — ritme in Berlijn op vrijdag, viool op zondag, een bas die All of Me kent.",
  "board.use.charts": "Charts voor vanavond — een setlist, een pdf, de akkoorden van een nummer dat de jam altijd overslaat.",
  "board.use.venue": "Podiumtip — een café waar je na tienen mag spelen, een achterzaal, een park dat nog werkt.",
  "board.use.other": "Overig — een lift naar de gig, een extra gitaar, een jam die je kunt aanbieden.",
