  "instruments.title": "Instrumenten",
  "instruments.lead":
    "Gypsy jazz is een kwintet: leadgitaar, la pompe, viool, contrabas — en daarna klarinet, zang, of een ander instrument. Hier staan de instrumenten en de bouwers. Lesmateriaal staat onder Leren.",
  "instruments.guitars": "Gitaren",
  "instruments.guitarsLead":
    "Gitaren in Selmer-Maccaferri-stijl — lead en pompe. Bouwers op bestelling, en winkels die ze op voorraad hebben.",
