  "organize.kicker": "Jamsessies",
  "organize.title": "Organiseer een jam",
  "organize.lead": "Een gypsy-jazzjam is een zaal, een paar gitaren en een avond in de agenda. Zo doe je dat. Zet hem daarna op de landpagina, zodat spelers je daar vinden.",
  "organize.1t": "Een plek en een tijd",
  "organize.1b": "Café, thuis, camping, park. Zet het exacte adres en van hoe laat tot hoe laat. Mensen moeten binnen kunnen lopen zonder te raden.",
  "organize.2t": "Akoestisch, in een cirkel",
  "organize.2b": "Eén ritmegitaar, één lead, bas als je die hebt. Dicht bij elkaar. Blijf akoestisch als het kan — dat is de sound.",
  "organize.3t": "Stukken die iedereen kent",
  "organize.3b": "Minor Swing, I’ll See You in My Dreams, Dark Eyes, Django’s Castle. Begin makkelijk, zodat amateurs meedoen. De cirkel groeit vanzelf.",
  "organize.4t": "Zet het op de hub",
  "organize.4b": "Log in, kies het land, zet de datum. Die landpagina is de agenda. Spelers daar zien jouw jam naast de anderen.",
  "organize.countries": "Kies je land",
  "organize.countriesLead": "In welk land organiseer je de jam? Kies het land, kijk wat er al is, en zet de jouwe erbij.",
