  "home.bannerAsk": "Stel een vraag",
  "home.joinTitle": "Word lid. Het is gratis.",
  "home.joinLead": "De muziek komt eerst. Daarna: mensen, plekken, vrienden — over de hele wereld. Iedereen mag lezen. Om iets te plaatsen vragen we een e-mail, zodat de site open blijft zonder spam.",
  "home.makePage": "Vind een avond",
