  "home.shareClip": "Deel een clip of een bericht",
  "home.shareClipBody": "Een set die je filmde, een bio, een podium. Het komt op de artiestenpagina, voor iedereen.",
  "join.kicker": "Gypsy Jazz Hub",
  "join.title": "Word lid van de hub",
  "join.free": "De site is gratis. Iedereen kan lezen. Om een datum of een notitie te plaatsen, log in met email — zodat we spam buiten houden.",
  "join.lead1": "Ik heb Gypsy Jazz Hub gemaakt zodat spelers, fans en bookers elkaar kunnen vinden. De muziek reist al. De mensen ook.",
  "join.lead2": "",
  "join.asideTitle": "Doe mee",
  "join.asideBody": "1. E-mail. 2. Kies een wachtwoord. 3. Typ het wachtwoord nog eens. Daarna ben je meteen ingelogd. We sturen een bevestigingsmail — dat is niet de inlog. Volgende keer: hetzelfde e-mailadres en wachtwoord.",
  "login.title": "Inloggen",
  "login.lead": "E-mail en het wachtwoord dat je koos bij aanmelden. Dat is alles.",
  "login.joinLink": "Nieuw hier? Lees wat lid worden is, en word lid.",
  "login.errorOauth": "Inloggen is niet gelukt. Probeer opnieuw met je e-mail.",
