  "join.1t": "Je eigen artiestenpagina — als je wilt",
  "join.1b": "Naam, land, instrument, een YouTube-video, komende avonden, en een contactlink voor bookers. Amateurs en professionals. Je kunt ook lid worden zonder pagina.",
  "join.2t": "Voeg een concert toe voor elke artiest",
  "join.2b": "Je hoorde dat Amati Schmitt speelt? Zet de avond op zijn pagina en op dat land op de globe. Fans houden de agenda levend — artiesten hebben het vaak te druk.",
  "join.3t": "Deel een YouTube-clip of een bio",
  "join.3b": "Een set die je filmde, een verhaal van een gig, waar iemand woont. Het komt op de artiestenpagina, voor iedereen.",
  "join.4t": "Voeg een festival, jam, zaal of luthier toe",
